 1	import React from 'react';
 2	import { chakra, useStyleConfig } from '@chakra-ui/react';
 3	import { ZimmProductName } from 'app/components/ui-kits/atoms/zimmProductName';
 4	import { ZimmProductPrice } from 'app/components/ui-kits/atoms/zimmProductPrice';
 5	import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription';
 6	
 7	const ZIMM_PRODUCT_CONTENT_RECIPE = 'ZimmProductContent';
 8	
 9	type ZimmProductContentProps = {
10	  /** The product's display name. */
11	  name: string;
12	  /**
13	   * Heading level for the name. Passed through rather than fixed here so the caller keeps
14	   * control of the page's heading outline — see `ZimmProductName`.
15	   */
16	  headingLevel: 'h1' | 'h2' | 'h3';
17	  /**
18	   * The price the shopper pays today, already formatted by the caller (e.g. "$450.00").
19	   * Optional: `ZimmProductPrice` renders nothing when absent or empty, so the flex gap
20	   * collapses cleanly.
21	   * — On sale: this is the *sale* price (the "Now" figure).
22	   * — Full price: this is the only price shown.
23	   */
24	  currentPrice?: string;
25	  /**
26	   * The original full price before the sale, already formatted (e.g. "$795.00").
27	   * Only supplied when the product is on sale (PRC-09). When present, `ZimmProductPrice`
28	   * switches to the Was/Now treatment — "Was {originalPrice} Now {currentPrice}".
29	   * Absent for full-price items.
30	   */
31	  originalPrice?: string;
32	  /** When true, the price atom renders an empty container while a variant re-fetch is in flight. */
33	  isPriceLoading?: boolean;
34	  /** Long description as authored in Business Manager. Omitted when the product has none. */
35	  description?: string;
36	};
37	
38	/**
39	 * Molecule — the PDP text group: name, price, description.
40	 *
41	 * Model copy and the style code are deliberately *not* here. The design places them at the
42	 * bottom of the column, after the accordions, so the page positions them itself rather than
43	 * this molecule holding them and then having to unpick the order.
44	 */
45	export const ZimmProductContent = ({
46	  name,
47	  headingLevel,
48	  currentPrice,
49	  originalPrice,
50	  isPriceLoading,
51	  description,
52	}: ZimmProductContentProps) => {
53	  const styles = useStyleConfig(ZIMM_PRODUCT_CONTENT_RECIPE, {});
54	
55	  return (
56	    <chakra.div __css={styles} data-testid="product-content">
57	      <ZimmProductName name={name} as={headingLevel} />
58	      <ZimmProductPrice currentPrice={currentPrice} originalPrice={originalPrice} isLoading={isPriceLoading} />
59	      <ZimmProductDescription description={description} />
60	    </chakra.div>
61	  );
62	};

