  1	/**
  2	 * Verifies the filtering and fallback logic of `selectVariantScopedPriceData`.
  3	 *
  4	 * `getPriceData` is mocked so every test asserts the *arguments* passed to it, not the
  5	 * value it returns. This proves the selector hands the right variant subset to the pricer
  6	 * rather than relying on getPriceData's own implementation to make the assertions meaningful.
  7	 *
  8	 * Branch coverage map (8 paths):
  9	 *  B1 – no selection → null (no urlPid, no urlColour)
 10	 *  B2 – colour-only → variants filtered by colour
 11	 *  B3 – pid + colour, pid belongs to colour → pid variant passed (happy path)
 12	 *  B4 – stale pid (pid's colour ≠ urlColour) → fallback to colour-only (Issue H regression)
 13	 *  B5 – pid only, no colour → pid variant passed directly
 14	 *  B6 – colour selected, no variants match → null
 15	 *  B7 – deep-link fallback (no masterVariants, has tieredPrices) → product passed as-is
 16	 *  B8 – deep-link, no tieredPrices → null
 17	 *  B9 – cached master identity mismatch → master discarded, null returned
 18	 * B10 – cached master matches via masterId → master's variants used
 19	 */
 20	import { afterEach, describe, expect, test, vi } from 'vitest';
 21	
 22	vi.mock('@salesforce/retail-react-app/app/utils/product-utils', () => ({
 23	  getPriceData: vi.fn(() => ({ currentPrice: 595 })),
 24	}));
 25	
 26	import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
 27	import { selectVariantScopedPriceData, type ScopedProduct } from './variantScopedPrice';
 28	
 29	const mockedGetPriceData = vi.mocked(getPriceData);
 30	
 31	// Sentinel colours so we can distinguish "which colour's variant" without reading test output
 32	const COLOUR_BLACK = 'black';
 33	const COLOUR_WHITE = 'white';
 34	
 35	// Minimal variants — productId and variationValues only (type index signature swallows the rest)
 36	const variantBlackSm = { productId: 'BLACK-SM', variationValues: { color: COLOUR_BLACK, size: 'S' } };
 37	const variantBlackMd = { productId: 'BLACK-MD', variationValues: { color: COLOUR_BLACK, size: 'M' } };
 38	const variantWhiteSm = { productId: 'WHITE-SM', variationValues: { color: COLOUR_WHITE, size: 'S' } };
 39	// White does NOT have an MD — used to test the stale-pid cross-check
 40	
 41	const masterWithAll: ScopedProduct = {
 42	  id: 'MASTER-001',
 43	  variants: [variantBlackSm, variantBlackMd, variantWhiteSm],
 44	};
 45	
 46	afterEach(() => {
 47	  vi.clearAllMocks();
 48	});
 49	
 50	// ─── B1: no selection ─────────────────────────────────────────────────────────
 51	
 52	describe('B1 — no url selection', () => {
 53	  test('returns null when neither urlPid nor urlColour is set', () => {
 54	    const result = selectVariantScopedPriceData(masterWithAll, null, undefined, undefined);
 55	    expect(result).toBeNull();
 56	    expect(mockedGetPriceData).not.toHaveBeenCalled();
 57	  });
 58	});
 59	
 60	// ─── B2: colour-only ─────────────────────────────────────────────────────────
 61	
 62	describe('B2 — colour-only selection', () => {
 63	  test('calls getPriceData with variants filtered to the selected colour', () => {
 64	    selectVariantScopedPriceData(masterWithAll, null, undefined, COLOUR_BLACK);
 65	    expect(mockedGetPriceData).toHaveBeenCalledOnce();
 66	    const [arg] = mockedGetPriceData.mock.calls[0];
 67	    expect((arg as ScopedProduct).variants).toEqual([variantBlackSm, variantBlackMd]);
 68	  });
 69	
 70	  test('scopes to white-only variants when white is selected', () => {
 71	    selectVariantScopedPriceData(masterWithAll, null, undefined, COLOUR_WHITE);
 72	    const [arg] = mockedGetPriceData.mock.calls[0];
 73	    expect((arg as ScopedProduct).variants).toEqual([variantWhiteSm]);
 74	  });
 75	});
 76	
 77	// ─── B3: pid + colour, happy path ────────────────────────────────────────────
 78	
 79	describe('B3 — pid + matching colour (happy path)', () => {
 80	  test('passes only the matching pid variant when pid and colour agree', () => {
 81	    selectVariantScopedPriceData(masterWithAll, null, 'BLACK-MD', COLOUR_BLACK);
 82	    const [arg] = mockedGetPriceData.mock.calls[0];
 83	    expect((arg as ScopedProduct).variants).toEqual([variantBlackMd]);
 84	  });
 85	});
 86	
 87	// ─── B4: stale pid (Issue H regression) ──────────────────────────────────────
 88	
 89	describe('B4 — stale-pid fallback (Issue H regression)', () => {
 90	  test('falls back to colour-only when the pid variant belongs to the OLD colour', () => {
 91	    // Shopper was on BLACK-MD (pid = 'BLACK-MD'), then switched to white.
 92	    // White has no MD — useVariant matched nothing, the pid-rewriting effect bailed out early,
 93	    // so the URL still has pid=BLACK-MD but color=white. Using the pid unchecked would show
 94	    // black's Was/Now price while white is selected — the exact bug this guard fixes.
 95	    selectVariantScopedPriceData(masterWithAll, null, 'BLACK-MD', COLOUR_WHITE);
 96	    const [arg] = mockedGetPriceData.mock.calls[0];
 97	    expect((arg as ScopedProduct).variants).toEqual([variantWhiteSm]);
 98	  });
 99	
100	  test('falls back to colour-only when pid matches no variant at all', () => {
101	    // pid is completely unknown (e.g. arrived via a deep-link to a discontinued sku)
102	    selectVariantScopedPriceData(masterWithAll, null, 'GHOST-PID', COLOUR_BLACK);
103	    const [arg] = mockedGetPriceData.mock.calls[0];
104	    expect((arg as ScopedProduct).variants).toEqual([variantBlackSm, variantBlackMd]);
105	  });
106	});
107	
108	// ─── B5: pid only, no colour ─────────────────────────────────────────────────
109	
110	describe('B5 — pid with no colour parameter', () => {
111	  test('passes the pid variant when only pid is set (no colour cross-check)', () => {
112	    selectVariantScopedPriceData(masterWithAll, null, 'WHITE-SM', undefined);
113	    const [arg] = mockedGetPriceData.mock.calls[0];
114	    expect((arg as ScopedProduct).variants).toEqual([variantWhiteSm]);
115	  });
116	});
117	
118	// ─── B6: colour selected, no variants match ───────────────────────────────────
119	
120	describe('B6 — colour selected but no matching variants', () => {
121	  test('returns null when colour matches zero variants', () => {
122	    const result = selectVariantScopedPriceData(masterWithAll, null, undefined, 'red');
123	    expect(result).toBeNull();
124	    expect(mockedGetPriceData).not.toHaveBeenCalled();
125	  });
126	});
127	
128	// ─── B7: deep-link fallback (no master, has tieredPrices) ────────────────────
129	
130	describe('B7 — deep-link fallback: no masterVariants, product has tieredPrices', () => {
131	  const standaloneVariant: ScopedProduct = {
132	    id: 'BLACK-SM',
133	    tieredPrices: [{ price: 595, pricebook: 'aud-pricebook' }],
134	    // No variants[] — this is a standalone variant response
135	  };
136	
137	  test('calls getPriceData with the product itself when master is absent', () => {
138	    selectVariantScopedPriceData(standaloneVariant, null, 'BLACK-SM', undefined);
139	    expect(mockedGetPriceData).toHaveBeenCalledOnce();
140	    expect(mockedGetPriceData.mock.calls[0][0]).toBe(standaloneVariant);
141	  });
142	
143	  test('also falls back when only colour is in the URL (no pid)', () => {
144	    selectVariantScopedPriceData(standaloneVariant, null, undefined, COLOUR_BLACK);
145	    expect(mockedGetPriceData).toHaveBeenCalledOnce();
146	    expect(mockedGetPriceData.mock.calls[0][0]).toBe(standaloneVariant);
147	  });
148	});
149	
150	// ─── B8: deep-link, no tieredPrices ─────────────────────────────────────────
151	
152	describe('B8 — deep-link with no tieredPrices', () => {
153	  test('returns null when product has no tieredPrices and no masterVariants are available', () => {
154	    const noTiered: ScopedProduct = { id: 'BLACK-SM' };
155	    const result = selectVariantScopedPriceData(noTiered, null, 'BLACK-SM', undefined);
156	    expect(result).toBeNull();
157	    expect(mockedGetPriceData).not.toHaveBeenCalled();
158	  });
159	});
160	
161	// ─── B9: cached master identity mismatch ─────────────────────────────────────
162	
163	describe('B9 — cached master identity mismatch', () => {
164	  test('does not use the cached master when it belongs to a different product', () => {
165	    // cachedMaster has variants but its id doesn't match — shopper navigated from a different PDP
166	    const differentMaster: ScopedProduct = {
167	      id: 'MASTER-DIFFERENT',
168	      variants: [variantBlackSm, variantBlackMd],
169	    };
170	    const currentProduct: ScopedProduct = {
171	      id: 'MASTER-CURRENT',
172	      // no variants[] of its own
173	    };
174	    const result = selectVariantScopedPriceData(currentProduct, differentMaster, undefined, COLOUR_BLACK);
175	    // cachedMaster is discarded → no masterVariants → deep-link check:
176	    // currentProduct has no tieredPrices → null
177	    expect(result).toBeNull();
178	    expect(mockedGetPriceData).not.toHaveBeenCalled();
179	  });
180	});
181	
182	// ─── B10: cached master matches via masterId ──────────────────────────────────
183	
184	describe('B10 — cached master matched by masterId', () => {
185	  test('uses the cached master variants when product.master.masterId matches cachedMaster.id', () => {
186	    // product is the standalone variant (no variants[]) but its master.masterId points at the cache
187	    const variantProduct: ScopedProduct = {
188	      id: 'BLACK-MD',
189	      master: { masterId: 'MASTER-001' }, // matches masterWithAll.id
190	    };
191	    selectVariantScopedPriceData(variantProduct, masterWithAll, undefined, COLOUR_BLACK);
192	    const [arg] = mockedGetPriceData.mock.calls[0];
193	    // Should have filtered masterWithAll's variants by COLOUR_BLACK
194	    expect((arg as ScopedProduct).variants).toEqual([variantBlackSm, variantBlackMd]);
195	  });
196	
197	  test('uses the cached master variants when product.id matches cachedMaster.id directly', () => {
198	    // Product IS the master but re-fetched (id matches) — race condition, shouldn't happen normally
199	    // but the selector doesn't care; positive identity match is enough
200	    const refetchedMaster: ScopedProduct = {
201	      id: 'MASTER-001',
202	      // no variants[] in this response shape
203	    };
204	    selectVariantScopedPriceData(refetchedMaster, masterWithAll, undefined, COLOUR_WHITE);
205	    const [arg] = mockedGetPriceData.mock.calls[0];
206	    expect((arg as ScopedProduct).variants).toEqual([variantWhiteSm]);
207	  });
208	});

