  9	import { selectPdpProductInfo, type PdpSourceProduct, type PdpSourcePrice } from './productInfo';
 10	
 11	/** Distinct sentinel per field — no two share a value. */
 12	const FULL: PdpSourceProduct = {
 13	  id: 'VARIANT-SKU-0001',
 14	  name: 'Natura Mini Dress',
 15	  longDescription: '<p>A long sleeve linen mini dress.</p>',
 16	  master: { masterId: 'MASTER-STYLE-8637' },
 17	  c_modelFit: 'Model is 178cm and wears a size 0',
 18	};
 19	
 20	const formatPrice = (amount: number, currency: string) => `${currency} ${amount.toFixed(2)}`;
 21	const map = (product: PdpSourceProduct | null | undefined, price: PdpSourcePrice | null = { currentPrice: 895 }) =>
 22	  selectPdpProductInfo(product, price, 'AUD', formatPrice);
 23	
 24	describe('selectPdpProductInfo — every field reaches the right prop', () => {
 25	  test.each`
 26	    prop             | source                      | expected
 27	    ${'name'}        | ${'name'}                   | ${'Natura Mini Dress'}
 28	    ${'description'} | ${'longDescription'}        | ${'<p>A long sleeve linen mini dress.</p>'}
 29	    ${'modelInfo'}   | ${'c_modelFit'}             | ${'Model is 178cm and wears a size 0'}
 30	    ${'styleCode'}   | ${'master.masterId'}        | ${'MASTER-STYLE-8637'}
 31	    ${'price'}       | ${'priceData.currentPrice'} | ${'AUD 895.00'}
 32	  `('$prop <- $source', ({ prop, expected }) => {
 33	    expect(map(FULL)?.[prop as keyof ReturnType<typeof map> & string]).toBe(expected);
 34	  });
 35	
 36	  test('styleCode is the master style number, not the variant id', () => {
 37	    // The regression this pins: after the first swatch click `product.id` becomes the variant
 38	    // SKU while the style code shown to shoppers must not change.
 39	    expect(map(FULL)?.styleCode).toBe('MASTER-STYLE-8637');
 40	    expect(map(FULL)?.styleCode).not.toBe(FULL.id);
 41	  });
 42	
 43	  test('falls back to product.id for a standard product with no master', () => {
 44	    expect(map({ ...FULL, master: undefined })?.styleCode).toBe('VARIANT-SKU-0001');
 45	  });
 46	});
 47	
 48	describe('selectPdpProductInfo — absent fields', () => {
 49	  test.each(['longDescription', 'c_modelFit', 'master'] as const)(
 50	    'a missing %s yields undefined, not a blank string',
 51	    (field) => {
 52	      const info = map({ ...FULL, [field]: undefined });
 53	      expect(info).not.toBeNull();
 54	      // `undefined` matters: the atoms branch on it to render nothing at all. An empty string
 55	      // would still be truthy at some call sites and could render an empty styled node.
 56	      const byField = { longDescription: 'description', c_modelFit: 'modelInfo', master: 'styleCode' } as const;
 57	      if (field !== 'master') expect(info?.[byField[field]]).toBeUndefined();
 58	    },
 59	  );
 60	
 61	  test('only name is load-bearing — no name means nothing to render yet', () => {
 62	    expect(map(undefined)).toBeNull();
