 79	describe('selectPdpProductInfo — formatting is delegated', () => {
 80	  test('calls the injected formatter once with the storefront currency', () => {
 81	    const spy = vi.fn(() => '$895.00');
 82	    selectPdpProductInfo(FULL, { currentPrice: 895 }, 'AUD', spy);
 83	    expect(spy).toHaveBeenCalledOnce();
 84	    expect(spy).toHaveBeenCalledWith(895, 'AUD');
 85	  });
 86	
 87	  test('does no formatting of its own', () => {
 88	    // Guards against a future edit reintroducing a hardcoded symbol or locale here; currency
 89	    // presentation differs across the 8 storefronts and belongs to react-intl.
 90	    expect(selectPdpProductInfo(FULL, { currentPrice: 895 }, 'HKD', (a, c) => `${c}${a}`)?.price).toBe('HKD895');
 91	  });
 92	});
 93	
 94	// ---------------------------------------------------------------------------
 95	// PRC-09 — Was/Now sale price (SFCC-194)
 96	// ---------------------------------------------------------------------------
 97	
 98	describe('selectPdpProductInfo — wasPrice (PRC-09)', () => {
 99	  const mapSale = (priceData: Parameters<typeof map>[1]) => map(FULL, priceData);
100	
101	  // AC1: sale active — wasPrice is the formatted listPrice
102	  test('returns wasPrice when isOnSale is true and listPrice is a number', () => {
103	    const info = mapSale({ currentPrice: 450, isOnSale: true, listPrice: 595 });
104	    expect(info?.wasPrice).toBe('AUD 595.00');
105	    expect(info?.price).toBe('AUD 450.00');
106	  });
107	
108	  // AC2: no sale — wasPrice is absent
109	  test('returns undefined wasPrice when isOnSale is false', () => {
110	    const info = mapSale({ currentPrice: 595, isOnSale: false, listPrice: 595 });
111	    expect(info?.wasPrice).toBeUndefined();
112	  });
113	
114	  // AC2: standard product (no priceData sale fields) — wasPrice is absent
115	  test('returns undefined wasPrice when isOnSale is absent', () => {
116	    const info = mapSale({ currentPrice: 595 });
117	    expect(info?.wasPrice).toBeUndefined();
118	  });
119	
120	  // AC4: sale expired — listPrice removed or equal to currentPrice, isOnSale becomes false
121	  test('returns undefined wasPrice when isOnSale is true but listPrice is absent', () => {
122	    // BM can mark isOnSale:true but provide no listPrice; the atom must not render "Was undefined"
123	    const info = mapSale({ currentPrice: 450, isOnSale: true, listPrice: undefined });
124	    expect(info?.wasPrice).toBeUndefined();
125	  });
126	
127	  // isRange guard: colour-only selection where sizes have different sale prices
128	  test('returns undefined wasPrice when isRange is true even if isOnSale and listPrice are present', () => {
129	    // currentPrice is the cheapest variant's price — not a definite settled figure.
130	    // Showing "Was $795 Now $595" would misrepresent the full colourway's pricing.
131	    const info = mapSale({ currentPrice: 595, isOnSale: true, listPrice: 795, isRange: true });
132	    expect(info?.wasPrice).toBeUndefined();
133	    // The selling price itself is still shown — only the Was/Now pair is suppressed.
134	    expect(info?.price).toBe('AUD 595.00');
135	  });
136	
137	  // AC5: sale flagged but currentPrice absent — wasPrice must not appear without a paired Now
138	  test('returns undefined wasPrice when isOnSale and listPrice are present but currentPrice is absent', () => {
139	    // getPriceData (external, untyped) can return isOnSale:true with no currentPrice in edge
140	    // cases. Without this guard the mapper would emit wasPrice without a matching price, and
141	    // any future consumer that doesn't also check currentPrice would render "Was $595" alone.
142	    const info = mapSale({ isOnSale: true, listPrice: 595, currentPrice: undefined });
143	    expect(info?.wasPrice).toBeUndefined();
144	    // price itself is also absent — confirmed by the existing absent-price test above
145	    expect(info?.price).toBe('');
146	  });
147	
148	  test('returns wasPrice when isRange is false (definite single-variant price)', () => {
149	    const info = mapSale({ currentPrice: 595, isOnSale: true, listPrice: 795, isRange: false });
150	    expect(info?.wasPrice).toBe('AUD 795.00');
151	  });
152	
153	  // Formatter is called for wasPrice with the same currency as price
154	  test('formats wasPrice with the same injected formatter and currency as price', () => {
155	    const spy = vi.fn((amount: number, currency: string) => `${currency}${amount}`);
156	    selectPdpProductInfo(FULL, { currentPrice: 450, isOnSale: true, listPrice: 595 }, 'AUD', spy);
157	    expect(spy).toHaveBeenCalledTimes(2);
158	    expect(spy).toHaveBeenCalledWith(595, 'AUD');
159	  });
160	});

