content.content:
  1	/**
  2	 * Scoped to this atom's own contract per testing.md: given a formatted string or nothing, does
  3	 * it render the right branch, and does the price it renders stay announceable.
  4	 *
  5	 * Formatting is deliberately not asserted here — it happens at the page
  6	 * (`selectPdpProductInfo`, proven in pages/product-detail/productInfo.test.ts) and this atom
  7	 * renders whatever string it is handed. What is not proven anywhere else is the absent branch:
  8	 * the mapper resolves a missing price to `''`, so the empty case is a real production path and
  9	 * not a defensive edge case.
 10	 *
 11	 * Every render is wrapped: the atom calls `useIntl()` for Was/Now labels, which throws outside
 12	 * an `IntlProvider` (react-intl's `invariantIntlContext`). `.storybook/preview.tsx` supplies
 13	 * one for stories; Vitest has no global provider, so it is supplied here.
 14	 */
 15	import React from 'react';
 16	import { describe, test, expect } from 'vitest';
 17	import { render, screen } from '@testing-library/react';
 18	import { IntlProvider } from 'react-intl';
 19	import { ZimmProductPrice } from './index';
 20	
 21	/** The ids the component asks for. Repeated deliberately — see the sourcing test below. */
 22	const WAS_LABEL_ID = 'product_view.label.was_price';
 23	const NOW_LABEL_ID = 'product_view.label.now_price';
 24	
 25	/**
 26	 * `locale` matches `defaultLocale` so react-intl treats an absent message as the ordinary
 27	 * fallback-to-`defaultMessage` path rather than a missing-translation error.
 28	 */
 29	const renderWithIntl = (ui: React.ReactElement, messages?: Record<string, string>) =>
 30	  render(
 31	    <IntlProvider locale="en-AU" defaultLocale="en-AU" messages={messages}>
 32	      {ui}
 33	    </IntlProvider>,
 34	  );
 35	
 36	describe('ZimmProductPrice', () => {
 37	  test('renders the caller-formatted string verbatim', () => {
 38	    renderWithIntl(<ZimmProductPrice currentPrice="HK$6,200.00" />);
 39	    // Verbatim, not re-formatted: the currency symbol, grouping and decimals are all the
 40	    // page's decisions, and re-deriving any of them here would diverge per storefront.
 41	    expect(screen.getByTestId('product-price').textContent).toBe('HK$6,200.00');
 42	  });
 43	
 44	  test('announces the price through a polite atomic live region', () => {
 45	    const { container } = renderWithIntl(<ZimmProductPrice currentPrice="HK$6,200.00" />);
 46	
 47	    // A variant change swaps this string with no focus move, so WCAG 2.2 AA 4.1.3 needs the
 48	    // update announced. Both attributes are asserted: dropping `aria-atomic` would let a screen
 49	    // reader announce only the characters that differ instead of the whole price, and neither
 50	    // loss shows up on screen, so nothing else would catch it.
 51	    const price = screen.getByTestId('product-price');
 52	    expect(price).toHaveAttribute('aria-live', 'polite');
 53	    expect(price).toHaveAttribute('aria-atomic', 'true');
 54	
 55	    // The live region is the price element itself, not an extra hidden twin. Asserted because
 56	    // the single-node shape is load-bearing, not incidental: `ZimmProductContent` renders this
 57	    // atom into a flex column whose own `play` tests assert that column's exact child count, so
 58	    // a second node here fails them from another folder.
 59	    expect(container.querySelectorAll('[aria-live]')).toHaveLength(1);
 60	    expect(container.firstChild).toBe(price);
 61	  });
 62	
 63	  // PRC-09 — Was/Now sale treatment
 64	  test('renders Was and Now spans when originalPrice is supplied', () => {
 65	    renderWithIntl(<ZimmProductPrice currentPrice="$450.00" originalPrice="$595.00" />);
 66	
 67	    expect(screen.getByTestId('product-was-price')).toHaveTextContent('Was $595.00');
 68	    expect(screen.getByTestId('product-now-price')).toHaveTextContent('Now $450.00');
 69	  });
 70	
 71	  test('combined textContent includes a separator space so aria-atomic reads correctly', () => {
 72	    // With aria-atomic="true" the whole container is read as one utterance. Without a text
 73	    // node between the two spans the announcement is "Was $795.00Now $595.00" — no separator.
 74	    renderWithIntl(<ZimmProductPrice currentPrice="$595.00" originalPrice="$795.00" />);
 75	    expect(screen.getByTestId('product-price').textContent).toBe('Was $795.00 Now $595.00');
 76	  });
 77	
 78	  test('Was/Now labels come from the intl provider, not from literals in the component', () => {
 79	    // Guards against regression to hardcoded English strings. The test above passes either
 80	    // way because `defaultMessage` and the old literal are the same string; supplying a
 81	    // different message for the same id is the only thing that tells them apart.
 82	    renderWithIntl(<ZimmProductPrice currentPrice="595,00 €" originalPrice="795,00 €" />, {
 83	      [WAS_LABEL_ID]: 'War {price}',
 84	      [NOW_LABEL_ID]: 'Jetzt {price}',
 85	    });
 86	    expect(screen.getByTestId('product-was-price').textContent).toBe('War 795,00 €');
 87	    expect(screen.getByTestId('product-now-price').textContent).toBe('Jetzt 595,00 €');
 88	  });
 89	
 90	  test('renders only the standard price when originalPrice is absent', () => {
 91	    renderWithIntl(<ZimmProductPrice currentPrice="$595.00" />);
 92	
 93	    expect(screen.queryByTestId('product-was-price')).not.toBeInTheDocument();
 94	    expect(screen.queryByTestId('product-now-price')).not.toBeInTheDocument();
 95	    expect(screen.getByTestId('product-price')).toHaveTextContent('$595.00');
 96	  });
 97	
 98	  test('live region remains a single element in the sale variant', () => {
 99	    // The live region must still be exactly one node (the chakra.p), even though its children
100	    // change. Two nodes would let ZimmProductContent's play tests break (child-count assertions).
101	    const { container } = renderWithIntl(<ZimmProductPrice currentPrice="$450.00" originalPrice="$595.00" />);
102	    expect(container.querySelectorAll('[aria-live]')).toHaveLength(1);
103	  });
104	
105	  // CodeRabbit a11y fix: live region must stay in the AT tree during loading so the
106	  // price announcement fires when the fetch settles.
107	  test('live region stays in the AT and preserves element identity across the loading transition', () => {
108	    const { rerender } = renderWithIntl(
109	      <ZimmProductPrice isLoading={true} currentPrice="$450.00" originalPrice="$595.00" />,
110	    );
111	
112	    const region = screen.getByTestId('product-price');
113	    // aria-hidden absence is required but not sufficient — visibility:hidden also removes the
114	    // element from the AT. opacity:0 is the correct visual-hiding technique here.
115	    expect(region).not.toHaveAttribute('aria-hidden');
116	    expect(region).not.toHaveStyle({ visibility: 'hidden' });
117	    expect(region).toHaveAttribute('aria-live', 'polite');
118	
119	    // Same DOM node after loading resolves — React reuses the chakra.p at the same position
120	    // so the AT's registered live region is preserved and announces the price on settle.
121	    rerender(
122	      <IntlProvider locale="en-AU" defaultLocale="en-AU">
123	        <ZimmProductPrice isLoading={false} currentPrice="$450.00" originalPrice="$595.00" />
124	      </IntlProvider>,
125	    );
126	    expect(screen.getByTestId('product-price')).toBe(region);
127	    expect(screen.getByTestId('product-was-price')).toHaveTextContent('Was $595.00');
128	    expect(screen.getByTestId('product-now-price')).toHaveTextContent('Now $450.00');
129	  });
130	
131	  test.each([undefined, ''])('renders nothing for %s', (currentPrice) => {
132	    const { container } = renderWithIntl(<ZimmProductPrice currentPrice={currentPrice} />);
133	    // `''` is what the page's mapper produces for a product with no price, so this branch is
134	    // reached in production. An empty styled node would still consume a gap in
135	    // ZimmProductContent's flex column, leaving a visible hole between name and description.
136	    //
137	    // Asserted as an empty container rather than an absent testid: a node that still carried the
138	    // recipe's styling but had lost its `data-testid` would satisfy the narrower check while
139	    // being precisely the gap-consuming element this guard exists to prevent.
140	    expect(container).toBeEmptyDOMElement();
141	  });
142	});

