131	  test.each([undefined, ''])('renders nothing for %s', (currentPrice) => {
132	    const { container } = renderWithIntl(<ZimmProductPrice currentPrice={currentPrice} />);
133	    // `''` is what the page's mapper produces for a product with no price, so this branch is
134	    // reached in production. An empty styled node would still consume a gap in
135	    // ZimmProductContent's flex column, leaving a visible hole between name and description.
136	    //
137	    // Asserted as an empty container rather than an absent testid: a node that still carried the
138	    // recipe's styling but had lost its `data-testid` would satisfy the narrower check while
139	    // being precisely the gap-consuming element this guard exists to prevent.
140	    expect(container).toBeEmptyDOMElement();
141	  });
142	});

